import React from 'react';
import { useParams } from 'react-router-dom';
import Sidebar from './Sidebar';

const dummyPost = {
    id: 1,
    title: 'Title',
    content: 'Exploring the cliffs was both breathtaking and humbling. The wind carried the scent of salt and sunshine, while the waves whispered stories of time. I never expected a spontaneous trip to bring such clarity. Sometimes the best journeys are the ones unplanned.Exploring the cliffs was both breathtaking and humbling. The wind carried the scent of salt and sunshine, while the waves whispered stories of time. I never expected a spontaneous trip to bring such clarity. Sometimes the best journeys are the ones unplanned.Exploring the cliffs was both breathtaking and humbling. The wind carried the scent of salt and sunshine, while the waves whispered stories of time. I never expected a spontaneous trip to bring such clarity. Sometimes the best journeys are the ones unplanned.Exploring the cliffs was both breathtaking and humbling. The wind carried the scent of salt and sunshine, while the waves whispered stories of time. I never expected a spontaneous trip to bring such clarity. Sometimes the best journeys are the ones unplanned.',
    imageUrl: 'https://picsum.photos/600/400',
    userName: 'User666B2C36',
    userAvatar: 'https://picsum.photos/40',
    location: 'Liaoning',
    updateTime: '02-22-25',
};

function PostDetail({ isLoggedIn }) {
    const { id } = useParams();
    const post = dummyPost; // later: fetch by id from server

    const [likes, setLikes] = React.useState(0);
    const [dislikes, setDislikes] = React.useState(0);
    const [liked, setLiked] = React.useState(false);
    const [disliked, setDisliked] = React.useState(false);

    const handleLike = () => {
        if (!isLoggedIn) return alert('Please login');
        if (!liked) {
            setLikes(likes + 1);
            if (disliked) {
                setDislikes(dislikes - 1);
                setDisliked(false);
            }
            setLiked(true);
        } else {
            setLikes(likes - 1);
            setLiked(false);
        }
    };

    const handleDislike = () => {
        if (!isLoggedIn) return alert('Please login');
        if (!disliked) {
            setDislikes(dislikes + 1);
            if (liked) {
                setLikes(likes - 1);
                setLiked(false);
            }
            setDisliked(true);
        } else {
            setDislikes(dislikes - 1);
            setDisliked(false);
        }
    };

    return (
        <div style={{ display: 'flex', height: '100vh' }}>
            <div style={{ flex: 1, padding: '24px', display: 'flex', backgroundColor: '#fff' }}>
                <div style={{ flex: 1 }}>
                    <img src={post.imageUrl} alt={post.title} style={{ width: '100%', borderRadius: '10px' }} />
                </div>
                <div style={{ width: '50%', padding: '0 24px', display: 'flex', flexDirection: 'column', justifyContent: 'flex-start', color: '#000' }}>
                    <div style={{ display: 'flex', alignItems: 'center', marginBottom: '10px' }}>
                        <img src={post.userAvatar} alt='avatar' style={{ width: '32px', height: '32px', borderRadius: '50%', marginRight: '8px' }} />
                        <span style={{ fontWeight: 'bold' }}>{post.userName}</span>
                    </div>
                    <h2 style={{ margin: '8px 0' }}>{post.title}</h2>
                    <p style={{ fontSize: '15px', marginBottom: '20px' }}>{post.content}</p>
                    <p style={{ color: '#888', fontSize: '13px' }}>📍 {post.location} · 🕓 {post.updateTime}</p>

                    <div style={{ marginTop: '20px', display: 'flex', gap: '20px' }}>
                        <div onClick={handleLike} style={{ cursor: 'pointer', display: 'flex', alignItems: 'center' }}>
                            <span style={{ fontSize: '18px', color: liked ? 'red' : 'gray', marginRight: '6px' }}>{liked ? '❤️' : '🤍'}</span>
                            <span>{likes}</span>
                        </div>
                        <div onClick={handleDislike} style={{ cursor: 'pointer', display: 'flex', alignItems: 'center' }}>
                            <span style={{ fontSize: '18px', color: disliked ? '#666' : 'gray', marginRight: '6px' }}>👎</span>
                            <span>{dislikes}</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

export default PostDetail;
